import React, { useState, useEffect } from 'react';
import { Sidebar } from './Sidebar.js';
import { CommandPalette } from './CommandPalette.js';
import { SettingsModal } from '../common/SettingsModal.js';

interface AppLayoutProps {
  children: React.ReactNode;
  currentView?: string;
  currentProjectId?: string;
  onNavigate?: (view: string, projectId?: string) => void;
}

export const AppLayout: React.FC<AppLayoutProps> = ({
  children,
  currentView = 'dashboard',
  currentProjectId,
  onNavigate,
}) => {
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Global Ctrl+K / Cmd+K listener
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        setIsCommandPaletteOpen((prev) => !prev);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  return (
    <div className="relative min-h-screen bg-background-surface text-foreground flex antialiased overflow-hidden">
      {/* Subtle Animated Ambient Background */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden z-0 select-none opacity-45">
        <div className="ambient-blob-1 absolute top-[-10%] left-[20%] w-[600px] h-[600px] rounded-full bg-indigo-500/10 blur-[150px]" />
        <div className="ambient-blob-2 absolute bottom-[-10%] right-[10%] w-[600px] h-[600px] rounded-full bg-emerald-500/10 blur-[150px]" />
      </div>

      {/* Fixed 64px Rail Sidebar */}
      <Sidebar
        currentView={currentView}
        currentProjectId={currentProjectId}
        onNavigate={onNavigate}
        onOpenCommandPalette={() => setIsCommandPaletteOpen(true)}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Content Area — offset by sidebar width */}
      <main className="relative z-10 flex-1 md:ml-16 ml-0 pb-14 md:pb-0 min-w-0 h-screen flex flex-col overflow-hidden">
        {children}
      </main>

      {/* Global Command Palette Overlay (Ctrl+K / Cmd+K) */}
      <CommandPalette
        isOpen={isCommandPaletteOpen}
        onClose={() => setIsCommandPaletteOpen(false)}
        onNavigate={onNavigate}
      />

      {/* Global Settings Modal Preferences Overlay */}
      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        onNavigate={onNavigate}
      />
    </div>
  );
};

export default AppLayout;
