/**
 * Graph Node Hover Inspection Tooltip
 * La Grande Bibliothèque — Milestone 4
 */

import React from 'react';
import type { GraphNode } from '../../types/graph.js';
import { ExternalLink, Tag, Layers, Share2, Lock } from 'lucide-react';

export interface GraphTooltipProps {
  node: GraphNode | null;
  screenX: number;
  screenY: number;
  containerWidth: number;
  containerHeight: number;
  onOpenProject?: (projectId: string) => void;
}

export const GraphTooltip: React.FC<GraphTooltipProps> = ({
  node,
  screenX,
  screenY,
  containerWidth,
  containerHeight,
  onOpenProject,
}) => {
  if (!node) return null;

  // Tooltip dimensions for collision detection
  const tooltipWidth = 260;
  const tooltipHeight = 180;
  const padding = 16;

  // Calculate position avoiding screen overflow
  let left = screenX + 16;
  let top = screenY + 16;

  if (left + tooltipWidth > containerWidth - padding) {
    left = screenX - tooltipWidth - 16;
  }
  if (top + tooltipHeight > containerHeight - padding) {
    top = screenY - tooltipHeight - 16;
  }

  left = Math.max(padding, left);
  top = Math.max(padding, top);

  return (
    <div
      className="absolute z-30 pointer-events-auto bg-background-surface border border-border rounded-xl p-4 shadow-md transition-all duration-150 animate-in fade-in zoom-in-95"
      style={{
        left: `${left}px`,
        top: `${top}px`,
        width: `${tooltipWidth}px`,
      }}
      data-testid="graph-tooltip"
    >
      <div className="flex items-start justify-between gap-2 mb-2">
        <h4 className="text-sm font-semibold text-foreground line-clamp-1 flex-1">
          {node.title}
        </h4>
        <span
          className="inline-flex items-center gap-1 text-[10px] font-medium px-2 py-0.5 rounded-full"
          style={{
            backgroundColor: `${node.clusterColor}20`,
            color: node.clusterColor,
            border: `1px solid ${node.clusterColor}40`,
          }}
        >
          Groupe {node.community + 1}
        </span>
      </div>

      {node.description && (
        <p className="text-xs text-foreground-muted line-clamp-2 mb-2.5">
          {node.description}
        </p>
      )}

      {/* Meta tags & category */}
      <div className="flex flex-wrap items-center gap-1.5 mb-3">
        {node.categoryName && (
          <span
            className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-md font-medium"
            style={{
              backgroundColor: `${node.categoryColor || '#6366f1'}22`,
              color: node.categoryColor || '#6366f1',
            }}
          >
            <Layers className="w-3 h-3" />
            {node.categoryName}
          </span>
        )}

        <span className="inline-flex items-center gap-1 text-[10px] text-foreground-subtle px-1.5 py-0.5 rounded bg-background-elevated border border-border">
          {node.space === 'personal' ? (
            <>
              <Lock className="w-2.5 h-2.5" /> Personnel
            </>
          ) : (
            <>
              <Share2 className="w-2.5 h-2.5" /> Partagé
            </>
          )}
        </span>

        <span className="text-[10px] text-foreground-subtle px-1.5 py-0.5 rounded bg-background-elevated border border-border">
          {node.degree} {node.degree === 1 ? 'connexion' : 'connexions'}
        </span>
      </div>

      {/* Tags */}
      {node.tags && node.tags.length > 0 && (
        <div className="flex flex-wrap gap-1 mb-3">
          {node.tags.slice(0, 3).map((tag) => (
            <span
              key={tag}
              className="inline-flex items-center gap-0.5 text-[10px] text-foreground-muted px-1.5 py-0.5 rounded bg-background-hover"
            >
              <Tag className="w-2.5 h-2.5 opacity-60" />
              {tag}
            </span>
          ))}
          {node.tags.length > 3 && (
            <span className="text-[10px] text-foreground-subtle">
              +{node.tags.length - 3}
            </span>
          )}
        </div>
      )}

      {/* Contextual Connection Reason */}
      {node.connectionReason && (
        <p className="text-[10px] text-accent font-medium mb-2.5 italic">
          {node.connectionReason}
        </p>
      )}

      {/* Open Button */}
      {onOpenProject && (
        <button
          onClick={() => onOpenProject(node.id)}
          className="w-full flex items-center justify-center gap-1.5 py-1.5 px-3 rounded-lg text-xs font-medium bg-accent hover:bg-accent-hover text-white transition-colors cursor-pointer"
        >
          <span>Ouvrir le livre</span>
          <ExternalLink className="w-3 h-3" />
        </button>
      )}
    </div>
  );
};
