import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import type { Category, Project } from '../../types/project.js';
import { api } from '../../lib/api.js';
import { cn } from '../../lib/utils.js';

export interface CreateProjectModalProps {
  isOpen: boolean;
  onClose: () => void;
  categories?: Category[];
  onSuccess?: (project: Project) => void;
  defaultType?: 'livre' | 'page' | 'feuille';
  defaultParentId?: string;
}

export const CreateProjectModal: React.FC<CreateProjectModalProps> = ({
  isOpen,
  onClose,
  categories = [],
  onSuccess,
  defaultType,
  defaultParentId,
}) => {
  const [projectType, setProjectType] = useState<'livre' | 'page' | 'feuille'>('livre');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [tags, setTags] = useState('');
  const [parentId, setParentId] = useState('');
  const [projectsList, setProjectsList] = useState<Project[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      setTitle('');
      setDescription('');
      setCategoryId('');
      setTags('');
      setParentId(defaultParentId || '');
      setProjectType(defaultType || 'livre');
      setError(null);

      // Fetch all projects for selection
      api.get<{ projects: Project[] }>('/api/projects')
        .then((res) => {
          const list = res.projects || [];
          setProjectsList(list);
          if (!defaultParentId) {
            const type = defaultType || 'livre';
            if (type === 'page') {
              const parents = list.filter((p) => !p.parentId);
              setParentId(parents[0]?.id || '');
            } else if (type === 'feuille') {
              const pages = list.filter((p) => p.parentId && !list.find(parent => parent.id === p.parentId)?.parentId);
              setParentId(pages[0]?.id || '');
            }
          }
        })
        .catch(() => {});
    }
  }, [isOpen, defaultType, defaultParentId]);

  // Handle Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    setIsSubmitting(true);
    setError(null);
    try {
      const tagList = tags
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean);

      const response = await api.post<{ project: Project }>('/api/projects', {
        title: title.trim(),
        description: description.trim(),
        space: 'personal',
        categoryId: categoryId || null,
        tags: tagList,
        parentId: projectType !== 'livre' ? (parentId || null) : null,
      });

      onSuccess?.(response.project);
      onClose();
    } catch (err: any) {
      setError(err.message || 'Échec de la création');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getPageParentTitle = (p: Project) => {
    const parent = projectsList.find((parentProj) => parentProj.id === p.parentId);
    return parent ? `${parent.title} > ${p.title}` : p.title;
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      data-testid="create-project-backdrop"
    >
      <div
        className="relative w-full max-w-md bg-background-surface border border-border rounded-xl p-6 shadow-xl text-foreground"
        onClick={(e) => e.stopPropagation()}
        data-testid="create-project-modal"
      >
        {/* Header */}
        <div className="flex items-center justify-between pb-3 border-b border-border mb-4">
          <h2 className="text-sm font-bold text-foreground">
            Créer un nouveau projet
          </h2>
          <button
            type="button"
            onClick={onClose}
            aria-label="Fermer"
            className="w-8 h-8 flex items-center justify-center rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && (
          <div className="mb-4 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-400 text-xs">
            {error}
          </div>
        )}

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Segmented Control for Entity Type */}
          <div className="space-y-1.5">
            <label className="block text-xs font-semibold text-foreground-muted">
              Type d'entité
            </label>
            <div className="grid grid-cols-3 gap-1 bg-background p-1 rounded-xl border border-border">
              {(['livre', 'page', 'feuille'] as const).map((type) => (
                <button
                  key={type}
                  type="button"
                  onClick={() => {
                    setProjectType(type);
                    if (type === 'page') {
                      const parents = projectsList.filter((p) => !p.parentId);
                      setParentId(parents[0]?.id || '');
                    } else if (type === 'feuille') {
                      const pages = projectsList.filter((p) => p.parentId && !projectsList.find(parent => parent.id === p.parentId)?.parentId);
                      setParentId(pages[0]?.id || '');
                    } else {
                      setParentId('');
                    }
                  }}
                  className={cn(
                    'py-1.5 rounded-lg text-xs font-semibold uppercase tracking-wider transition-all cursor-pointer text-center',
                    projectType === type
                      ? 'bg-foreground text-background shadow-xs'
                      : 'text-foreground-muted hover:text-foreground'
                  )}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-foreground-muted mb-1">
              Titre *
            </label>
            <input
              type="text"
              required
              autoFocus
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={`ex. Titre du ${projectType}`}
              className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-foreground-muted mb-1">
              Description
            </label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Description courte..."
              className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors"
            />
          </div>

          {projectType === 'livre' && (
            <div>
              <label className="block text-xs font-semibold text-foreground-muted mb-1">
                Catégorie
              </label>
              <select
                value={categoryId}
                onChange={(e) => setCategoryId(e.target.value)}
                className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors cursor-pointer"
              >
                <option value="">Sans catégorie</option>
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </div>
          )}

          {projectType === 'page' && (
            <div>
              <label className="block text-xs font-semibold text-foreground-muted mb-1">
                Livre principal *
              </label>
              <select
                value={parentId}
                required
                onChange={(e) => setParentId(e.target.value)}
                className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors cursor-pointer"
              >
                <option value="" disabled>Sélectionner un livre...</option>
                {projectsList
                  .filter((p) => !p.parentId)
                  .map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.title}
                    </option>
                  ))}
              </select>
            </div>
          )}

          {projectType === 'feuille' && (
            <div>
              <label className="block text-xs font-semibold text-foreground-muted mb-1">
                Page parente *
              </label>
              <select
                value={parentId}
                required
                onChange={(e) => setParentId(e.target.value)}
                className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors cursor-pointer"
              >
                <option value="" disabled>Sélectionner une page...</option>
                {projectsList
                  .filter((p) => p.parentId && !projectsList.find(parent => parent.id === p.parentId)?.parentId)
                  .map((p) => (
                    <option key={p.id} value={p.id}>
                      {getPageParentTitle(p)}
                    </option>
                  ))}
              </select>
            </div>
          )}

          <div>
            <label className="block text-xs font-semibold text-foreground-muted mb-1">
              Tags (séparés par des virgules)
            </label>
            <input
              type="text"
              value={tags}
              onChange={(e) => setTags(e.target.value)}
              placeholder="musique, beat, design"
              className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors"
            />
          </div>

          <div className="flex items-center justify-end gap-2 pt-4 border-t border-border">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-lg text-xs font-medium text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
            >
              Annuler
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !title.trim() || (projectType !== 'livre' && !parentId)}
              className="px-4 py-2 bg-foreground text-background rounded-lg text-xs font-semibold disabled:opacity-50 hover:opacity-85 transition-all cursor-pointer"
            >
              {isSubmitting ? 'Création...' : 'Créer'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateProjectModal;
