import React, { useState, useMemo } from 'react';
import { createPortal } from 'react-dom';
import type { MarkdownBlockContent } from '../../../types/block.js';
import { Edit3, Eye, Columns } from 'lucide-react';

interface MarkdownBlockProps {
  content: MarkdownBlockContent;
  onChange: (content: MarkdownBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

// Lightweight secure markdown renderer
function renderMarkdownToHtml(markdown: string): string {
  if (!markdown) return '';

  let html = markdown
    // Escape HTML special characters
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Code blocks: ```lang ... ```
  html = html.replace(/```([\s\S]*?)```/g, (_match, code) => {
    return `<pre class="bg-background-surface border border-border p-3 rounded-lg my-2 overflow-x-auto text-sm font-mono text-foreground-accent"><code>${code.trim()}</code></pre>`;
  });

  // Headers: ###, ##, #
  html = html.replace(/^### (.*$)/gim, '<h3 class="text-lg font-bold text-foreground mt-3 mb-1">$1</h3>');
  html = html.replace(/^## (.*$)/gim, '<h2 class="text-xl font-bold text-foreground mt-4 mb-2">$1</h2>');
  html = html.replace(/^# (.*$)/gim, '<h1 class="text-2xl font-black text-foreground mt-4 mb-2 pb-1 border-b border-border">$1</h1>');

  // Blockquotes: > quote
  html = html.replace(/^> (.*$)/gim, '<blockquote class="border-l-4 border-accent pl-4 py-1.5 my-2 text-foreground-muted italic bg-background-surface/50 rounded-r text-base">$1</blockquote>');

  // Checklists: - [x] or - [ ]
  html = html.replace(/^- \[(x|X)\] (.*$)/gim, '<div class="flex items-center gap-2 my-1"><input type="checkbox" checked disabled class="accent-accent rounded"/><span class="line-through text-foreground-muted text-base">$2</span></div>');
  html = html.replace(/^- \[ \] (.*$)/gim, '<div class="flex items-center gap-2 my-1"><input type="checkbox" disabled class="accent-accent rounded"/><span class="text-foreground text-base">$2</span></div>');

  // Unordered Lists: - item
  html = html.replace(/^- (.*$)/gim, '<li class="ml-4 list-disc text-base text-foreground my-0.5">$1</li>');

  // Ordered Lists: 1. item
  html = html.replace(/^\d+\. (.*$)/gim, '<li class="ml-4 list-decimal text-base text-foreground my-0.5">$1</li>');

  // Bold & Italic
  html = html.replace(/\*\*\*(.*?)\*\*\*/g, '<strong class="font-bold"><em>$1</em></strong>');
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong class="font-bold text-foreground">$1</strong>');
  html = html.replace(/\*(.*?)\*/g, '<em class="italic text-foreground-muted">$1</em>');
  html = html.replace(/~~(.*?)~~/g, '<del class="line-through text-foreground-muted">$1</del>');

  // Inline Code: `code`
  html = html.replace(/`([^`]+)`/g, '<code class="bg-background-surface px-2 py-0.5 rounded text-sm font-mono text-accent border border-border/50">$1</code>');

  // Links: [text](url)
  html = html.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" class="text-accent underline hover:text-accent/80 font-medium">$1</a>');

  // Paragraphs / Newlines
  html = html.replace(/\n\n+/g, '</p><p class="my-2 leading-relaxed text-base">');
  html = html.replace(/\n/g, '<br/>');

  return `<div class="prose prose-invert max-w-none text-foreground text-base leading-relaxed">${html}</div>`;
}

export const MarkdownBlock: React.FC<MarkdownBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const [mode, setMode] = useState<'edit' | 'preview' | 'split'>('split');
  const markdownText = content.markdown || '';

  const { wordCount, charCount } = useMemo(() => {
    const trimmed = markdownText.trim();
    return {
      wordCount: trimmed ? trimmed.split(/\s+/).length : 0,
      charCount: markdownText.length,
    };
  }, [markdownText]);

  const renderedHtml = useMemo(() => renderMarkdownToHtml(markdownText), [markdownText]);

  // When toolbar is hidden (resting Notion state), always render clean preview!
  if (!isToolbarVisible && !readOnly) {
    return (
      <div className="w-full py-1 text-foreground">
        {markdownText.trim() ? (
          <div
            dangerouslySetInnerHTML={{ __html: renderedHtml }}
            className="prose prose-invert max-w-none text-base"
          />
        ) : (
          <p className="text-foreground-muted/50 text-base italic">
            Bloc markdown vide... Cliquez pour rédiger
          </p>
        )}
      </div>
    );
  }

  const toolbarElement = typeof document !== 'undefined' ? document.getElementById('canvas-floating-toolbar-portal') : null;

  const toolbar = (
    <div className="flex items-center gap-1">
      <span className="text-[10px] uppercase font-mono font-semibold tracking-wider text-foreground-muted px-2 border-r border-border mr-1 select-none">
        Markdown
      </span>
      <button
        type="button"
        onClick={() => setMode('edit')}
        className={`flex items-center gap-1 px-2 py-1 rounded-md transition-colors cursor-pointer ${
          mode === 'edit'
            ? 'bg-accent text-accent-foreground font-semibold shadow-sm'
            : 'hover:text-foreground hover:bg-background-hover text-foreground-muted'
        }`}
        title="Éditer le markdown"
      >
        <Edit3 className="w-3.5 h-3.5" />
        <span className="text-xs">Éditer</span>
      </button>
      <button
        type="button"
        onClick={() => setMode('split')}
        className={`flex items-center gap-1 px-2 py-1 rounded-md transition-colors cursor-pointer ${
          mode === 'split'
            ? 'bg-accent text-accent-foreground font-semibold shadow-sm'
            : 'hover:text-foreground hover:bg-background-hover text-foreground-muted'
        }`}
        title="Mode scindé"
      >
        <Columns className="w-3.5 h-3.5" />
        <span className="text-xs">Scindé</span>
      </button>
      <button
        type="button"
        onClick={() => setMode('preview')}
        className={`flex items-center gap-1 px-2 py-1 rounded-md transition-colors cursor-pointer ${
          mode === 'preview'
            ? 'bg-accent text-accent-foreground font-semibold shadow-sm'
            : 'hover:text-foreground hover:bg-background-hover text-foreground-muted'
        }`}
        title="Aperçu"
      >
        <Eye className="w-3.5 h-3.5" />
        <span className="text-xs">Aperçu</span>
      </button>
    </div>
  );

  return (
    <div className="w-full rounded-lg overflow-hidden flex flex-col transition-all">
      {/* Header Toolbar */}
      {isToolbarVisible && !readOnly && (
        toolbarElement ? createPortal(toolbar, toolbarElement) : (
          <div className="flex items-center justify-between px-3 py-2 bg-background-surface border border-border rounded-t-lg text-xs text-foreground-muted select-none animate-in fade-in duration-150">
            {toolbar}
          </div>
        )
      )}

      {/* Editor & Preview Panes */}
      <div className={`grid grid-cols-1 md:grid-cols-2 divide-y md:divide-y-0 md:divide-x divide-border min-h-[140px] ${
        isToolbarVisible && !toolbarElement ? 'border-x border-b border-border bg-card/60 rounded-b-lg' : 'border border-border/40 bg-card/45 rounded-lg'
      }`}>
        {(mode === 'edit' || mode === 'split') && (
          <div className={`p-3 flex flex-col ${mode === 'edit' ? 'col-span-full' : ''}`}>
            <textarea
              value={markdownText}
              disabled={readOnly}
              onChange={(e) => onChange({ markdown: e.target.value })}
              placeholder="# Titre&#10;&#10;Écrivez vos notes en markdown..."
              className="w-full h-full min-h-[140px] bg-transparent text-foreground font-mono text-sm leading-relaxed focus:outline-none resize-y"
            />
          </div>
        )}

        {(mode === 'preview' || mode === 'split') && (
          <div
            className={`p-4 bg-background/40 overflow-y-auto max-h-[500px] ${
              mode === 'preview' ? 'col-span-full' : ''
            }`}
          >
            {markdownText.trim() ? (
              <div
                dangerouslySetInnerHTML={{ __html: renderedHtml }}
                className="prose prose-invert max-w-none text-base"
              />
            ) : (
              <p className="text-foreground-muted text-sm italic">
                Aperçu markdown...
              </p>
            )}
          </div>
        )}
      </div>

      {/* Footer Info */}
      {isToolbarVisible && (
        <div className="flex items-center justify-between px-3 py-1.5 bg-background-surface/50 border-x border-b border-border rounded-b-lg text-xs font-mono text-foreground-muted">
          <span>{wordCount} mots &bull; {charCount} caractères</span>
          <span>GFM Markdown</span>
        </div>
      )}
    </div>
  );
};
