/**
 * 2D Force-Directed Physics Simulation Engine
 * La Grande Bibliothèque — Milestone 4 (Feature 18 & Feature 19)
 * 
 * Implements:
 * 1. Coulomb Repulsion with soft epsilon and coincident perturbation
 * 2. Hooke Spring Attraction modulated by semantic similarity
 * 3. Centering Gravity pulling corpus towards viewport origin
 * 4. Degree-Dependent Hub Radial Orbit Gravity (hub inwards, leaves outwards)
 * 5. Constellation Cluster Centroid Attraction
 * 6. Euler Velocity Integration with Damping and Speed Clamping (<= 15 px/frame)
 * 7. Kinetic Pinning for focal/dragged nodes
 */

export interface PhysicsSimulationNode {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  degree: number;
  community?: number;
  pinned?: boolean;
  radius?: number;
  parentId?: string | null;
}

export interface PhysicsSimulationEdge {
  source: string;
  target: string;
  similarity?: number;
  weight?: number;
}

export interface PhysicsSimulationOptions {
  dt?: number;
  kRepel?: number;
  kSpring?: number;
  kGrav?: number;
  kRadial?: number;
  kCluster?: number;
  centerX?: number;
  centerY?: number;
  damping?: number;
  maxVelocity?: number;
}

/**
 * Executes a single discrete integration step of the force-directed physics engine.
 */
export function simulateForceDirectedStep(
  nodes: PhysicsSimulationNode[],
  edges: PhysicsSimulationEdge[],
  options: PhysicsSimulationOptions = {}
): void {
  const dt = options.dt ?? 1.0;
  const kRepel = options.kRepel ?? -8000.0;
  const kSpring = options.kSpring ?? 0.035;
  const kGrav = options.kGrav ?? 0.01;
  const kRadial = options.kRadial ?? 0.02;
  const kCluster = options.kCluster ?? 0.015;
  const centerX = options.centerX ?? 400;
  const centerY = options.centerY ?? 300;
  const damping = options.damping ?? 0.85;
  const maxVelocity = options.maxVelocity ?? 15.0;
  const softEpsilon = 12.0;

  const n = nodes.length;
  if (n === 0) return;

  const nodeMap = new Map<string, PhysicsSimulationNode>();
  for (const node of nodes) {
    nodeMap.set(node.id, node);
  }

  const forces = new Map<string, { fx: number; fy: number }>();
  for (const node of nodes) {
    forces.set(node.id, { fx: 0, fy: 0 });
  }

  // 1. Coulomb Repulsion (All pairs i < j)
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const n1 = nodes[i];
      const n2 = nodes[j];
      let dx = n2.x - n1.x;
      let dy = n2.y - n1.y;

      if (Math.abs(dx) < 1e-6 && Math.abs(dy) < 1e-6) {
        // Distinct nodes with coincident coordinates: inject deterministic perturbation
        const angle = (((i + 1) * 37 + (j + 1) * 17) % 360) * (Math.PI / 180);
        dx = Math.cos(angle) * 0.1;
        dy = Math.sin(angle) * 0.1;
      }

      const dist = Math.sqrt(dx * dx + dy * dy) + softEpsilon;
      const forceMag = kRepel / (dist * dist);
      const fx = (dx / dist) * forceMag;
      const fy = (dy / dist) * forceMag;

      const f1 = forces.get(n1.id)!;
      const f2 = forces.get(n2.id)!;
      f1.fx += fx;
      f1.fy += fy;
      f2.fx -= fx;
      f2.fy -= fy;
    }
  }

  // 2. Hooke Spring Attraction (Connected pairs)
  for (const edge of edges) {
    const sNode = nodeMap.get(edge.source);
    const tNode = nodeMap.get(edge.target);
    if (!sNode || !tNode) continue;

    const dx = tNode.x - sNode.x;
    const dy = tNode.y - sNode.y;
    const dist = Math.sqrt(dx * dx + dy * dy) + 0.001;
    const sim = edge.similarity ?? edge.weight ?? 0.5;
    const restLength = 220.0 * (1.0 - 0.4 * Math.max(0, Math.min(1, sim)));
    const springForce = kSpring * (dist - restLength);

    const fx = (dx / dist) * springForce;
    const fy = (dy / dist) * springForce;

    const fs = forces.get(sNode.id)!;
    const ft = forces.get(tNode.id)!;
    fs.fx += fx;
    fs.fy += fy;
    ft.fx -= fx;
    ft.fy -= fy;
  }

  // 3. Constellation Cluster Centroid Attraction
  const clusterCentroids = computeClusterCentroids(nodes);
  if (clusterCentroids.size > 0 && kCluster > 0) {
    for (const node of nodes) {
      if (node.community !== undefined && clusterCentroids.has(node.community)) {
        const centroid = clusterCentroids.get(node.community)!;
        const f = forces.get(node.id)!;
        f.fx += (centroid.x - node.x) * kCluster;
        f.fy += (centroid.y - node.y) * kCluster;
      }
    }
  }

  // 4. Centering Gravity & Hierarchical Radial Orbit Gravity (Neural Constellation Layout)
  for (const node of nodes) {
    const f = forces.get(node.id)!;

    // Direct centering pull
    f.fx += (centerX - node.x) * kGrav;
    f.fy += (centerY - node.y) * kGrav;

    // Calculate hierarchical level (0 for Livre, 1 for Page, 2 for Feuille)
    let level = 0;
    let curr = node;
    while (curr && curr.parentId && nodeMap.has(curr.parentId)) {
      level++;
      curr = nodeMap.get(curr.parentId)!;
    }

    let targetOrbit = 0;
    if (level === 0) {
      targetOrbit = 70.0;
    } else if (level === 1) {
      targetOrbit = 240.0;
    } else {
      targetOrbit = 420.0;
    }

    const curDx = node.x - centerX;
    const curDy = node.y - centerY;
    const curR = Math.sqrt(curDx * curDx + curDy * curDy) + 0.001;
    const radialError = curR - targetOrbit;

    // Apply radial force targeting the orbit radius
    f.fx -= (curDx / curR) * radialError * kRadial;
    f.fy -= (curDy / curR) * radialError * kRadial;
  }

  // 4.5 Collision Force (Prevent overlaps)
  const padding = 35.0; // Distance buffer between node borders to ensure breathing space
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      const n1 = nodes[i];
      const n2 = nodes[j];
      const r1 = n1.radius ?? 15.0;
      const r2 = n2.radius ?? 15.0;
      const minDist = r1 + r2 + padding;

      const dx = n2.x - n1.x;
      const dy = n2.y - n1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < minDist && dist > 0.001) {
        const overlap = minDist - dist;
        const pushForce = 0.55;
        const fx = (dx / dist) * overlap * pushForce;
        const fy = (dy / dist) * overlap * pushForce;

        const f1 = forces.get(n1.id)!;
        f1.fx -= fx;
        f1.fy -= fy;
      }
    }
  }

  // 5. Update Velocities, Damping, Speed Clamping & Positions
  for (const node of nodes) {
    if (node.pinned) {
      node.vx = 0;
      node.vy = 0;
      continue;
    }

    const f = forces.get(node.id)!;
    node.vx = (node.vx + f.fx * dt) * damping;
    node.vy = (node.vy + f.fy * dt) * damping;

    // Cap max velocity to prevent kinetic divergence
    const speed = Math.sqrt(node.vx * node.vx + node.vy * node.vy);
    if (speed > maxVelocity) {
      node.vx = (node.vx / speed) * maxVelocity;
      node.vy = (node.vy / speed) * maxVelocity;
    }

    node.x += node.vx * dt;
    node.y += node.vy * dt;
  }
}

/**
 * Calculates geometric centroids for all community clusters.
 */
export function computeClusterCentroids(
  nodes: PhysicsSimulationNode[]
): Map<number, { x: number; y: number; count: number }> {
  const centroidMap = new Map<number, { sumX: number; sumY: number; count: number }>();

  for (const node of nodes) {
    if (node.community === undefined) continue;
    const entry = centroidMap.get(node.community) ?? { sumX: 0, sumY: 0, count: 0 };
    entry.sumX += node.x;
    entry.sumY += node.y;
    entry.count += 1;
    centroidMap.set(node.community, entry);
  }

  const result = new Map<number, { x: number; y: number; count: number }>();
  for (const [comm, entry] of centroidMap.entries()) {
    if (entry.count > 0) {
      result.set(comm, {
        x: entry.sumX / entry.count,
        y: entry.sumY / entry.count,
        count: entry.count,
      });
    }
  }

  return result;
}

/**
 * Computes total kinetic energy of the simulation to detect convergence.
 */
export function calculateGraphKineticEnergy(nodes: PhysicsSimulationNode[]): number {
  let totalEnergy = 0;
  for (const n of nodes) {
    if (!n.pinned) {
      totalEnergy += 0.5 * (n.vx * n.vx + n.vy * n.vy);
    }
  }
  return totalEnergy;
}

/**
 * Initializes nodes on a golden spiral distribution around the center.
 */
export function initializeNodePositions(
  nodes: PhysicsSimulationNode[],
  centerX: number,
  centerY: number,
  focalId?: string
): void {
  const phi = (1 + Math.sqrt(5)) / 2; // Golden ratio
  const angleIncrement = 2 * Math.PI * (1 - 1 / phi); // ~137.5 degrees
  const spreadRadius = 45.0;

  nodes.forEach((node, i) => {
    if (focalId && node.id === focalId) {
      node.x = centerX;
      node.y = centerY;
      node.vx = 0;
      node.vy = 0;
      node.pinned = true;
      return;
    }

    if (node.x === undefined || node.y === undefined || (node.x === 0 && node.y === 0)) {
      const r = spreadRadius * Math.sqrt(i + 1);
      const theta = i * angleIncrement;
      node.x = centerX + r * Math.cos(theta);
      node.y = centerY + r * Math.sin(theta);
    }

    node.vx = 0;
    node.vy = 0;
  });
}
