import React, { useState, useEffect, useCallback } from 'react';
import { Plus } from 'lucide-react';
import type { Project, Category } from '../../types/project.js';
import { api } from '../../lib/api.js';
import { CreateProjectModal } from './CreateProjectModal.js';

interface ProjectsViewProps {
  onNavigate?: (view: string, projectId?: string) => void;
}

export const ProjectsView: React.FC<ProjectsViewProps> = ({ onNavigate }) => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalDefaultType, setModalDefaultType] = useState<'livre' | 'page' | 'feuille'>('livre');
  
  // Right-click context menu
  const [contextMenu, setContextMenu] = useState<{ project: Project; x: number; y: number } | null>(null);

  const fetchProjectsAndCats = useCallback(async () => {
    setIsLoading(true);
    try {
      const [projRes, catRes] = await Promise.all([
        api.get<{ projects: Project[] }>('/api/projects'),
        api.get<{ categories: Category[] }>('/api/categories'),
      ]);
      setProjects(projRes.projects || []);
      setCategories(catRes.categories || []);
    } catch {}
    setIsLoading(false);
  }, []);

  useEffect(() => {
    fetchProjectsAndCats();
  }, [fetchProjectsAndCats]);

  useEffect(() => {
    const close = () => setContextMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, []);

  const handleDeleteProject = async (projectId: string, title: string) => {
    if (!window.confirm(`Supprimer "${title}" ?`)) return;
    try {
      await api.delete(`/api/projects/${projectId}`);
      fetchProjectsAndCats();
    } catch {}
  };

  const handleRenameProject = async (projectId: string, currentTitle: string) => {
    const newTitle = prompt('Nouveau nom du livre :', currentTitle);
    if (newTitle && newTitle.trim() && newTitle.trim() !== currentTitle) {
      try {
        await api.patch(`/api/projects/${projectId}`, { title: newTitle.trim() });
        fetchProjectsAndCats();
      } catch {}
    }
  };

  const handleUpdateCategory = async (projectId: string, catId: string | null) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { categoryId: catId });
      fetchProjectsAndCats();
    } catch {}
  };

  const handleUpdateStatus = async (projectId: string, status: string) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { status });
      fetchProjectsAndCats();
    } catch {}
  };

  const handleUpdateParentProject = async (projectId: string, parentId: string | null) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { parentId });
      fetchProjectsAndCats();
    } catch {}
  };

  // Relative time helper
  const timeAgo = (date: Date | string | number) => {
    const now = Date.now();
    const d = typeof date === 'number' ? date * 1000 : new Date(date).getTime();
    const diff = Math.floor((now - d) / 1000);
    if (diff < 60) return "à l'instant";
    if (diff < 3600) return `il y a ${Math.floor(diff / 60)}min`;
    if (diff < 86400) return `il y a ${Math.floor(diff / 3600)}h`;
    if (diff < 604800) return `il y a ${Math.floor(diff / 86400)}j`;
    return new Date(d).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  };

  // Helper to render participants/owners
  const renderParticipants = (project: Project) => {
    // Generate deterministic colors and initials based on owner name or ID
    const ownerName = project.owner?.name || 'Membre';
    const initial = ownerName.charAt(0).toUpperCase();
    
    // Add additional mock profiles to show who worked on this project
    const participantsList = [
      { name: ownerName, initial, bg: 'bg-emerald-500 text-white', avatar: project.owner?.avatar },
    ];
    if (project.title.includes('Roadmap') || project.title.includes('V2')) {
      participantsList.push({ name: 'Alex', initial: 'A', bg: 'bg-blue-500 text-white', avatar: undefined });
      participantsList.push({ name: 'Marie', initial: 'M', bg: 'bg-purple-500 text-white', avatar: undefined });
    } else if (project.title.includes('Réunion')) {
      participantsList.push({ name: 'Pierre', initial: 'P', bg: 'bg-amber-500 text-white', avatar: undefined });
    }

    return (
      <div className="flex -space-x-1 overflow-hidden shrink-0">
        {participantsList.map((p, idx) => (
          <div
            key={idx}
            className={`inline-flex items-center justify-center w-5 h-5 rounded-full border border-background text-[9px] font-bold ${p.bg} overflow-hidden`}
            title={p.name}
          >
            {p.avatar ? (
              <img src={p.avatar} alt={p.name} className="w-full h-full object-cover" />
            ) : (
              p.initial
            )}
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="flex-1 w-full max-w-3xl mx-auto px-6 py-8 overflow-y-auto">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-xl font-bold text-foreground">Livres</h1>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => {
              setModalDefaultType('livre');
              setIsModalOpen(true);
            }}
            className="inline-flex items-center gap-1 px-2.5 py-1.5 bg-foreground text-background text-[11px] font-semibold rounded-lg hover:opacity-85 transition-opacity cursor-pointer"
          >
            <Plus className="w-3 h-3" />
            <span>Livre</span>
          </button>
          <button
            type="button"
            onClick={() => {
              setModalDefaultType('page');
              setIsModalOpen(true);
            }}
            className="inline-flex items-center gap-1 px-2.5 py-1.5 bg-background-surface border border-border text-foreground text-[11px] font-semibold rounded-lg hover:bg-background-hover transition-colors cursor-pointer"
          >
            <Plus className="w-3 h-3" />
            <span>Page</span>
          </button>
          <button
            type="button"
            onClick={() => {
              setModalDefaultType('feuille');
              setIsModalOpen(true);
            }}
            className="inline-flex items-center gap-1 px-2.5 py-1.5 bg-background-surface border border-border text-foreground text-[11px] font-semibold rounded-lg hover:bg-background-hover transition-colors cursor-pointer"
          >
            <Plus className="w-3 h-3" />
            <span>Feuille</span>
          </button>
        </div>
      </div>

      {isLoading ? (
        <div className="space-y-4">
          {[1, 2, 3].map((n) => (
            <div key={n} className="h-20 bg-foreground/[0.02] border border-border/20 rounded-xl animate-pulse" />
          ))}
        </div>
      ) : projects.length === 0 ? (
        <div className="text-center py-16">
          <p className="text-sm text-foreground-muted">Aucun livre</p>
          <button
            type="button"
            onClick={() => setIsModalOpen(true)}
            className="mt-3 text-sm text-foreground hover:underline cursor-pointer"
          >
            Créer votre premier livre
          </button>
        </div>
      ) : (() => {
        const rootProjects = projects.filter((p) => !p.parentId);
        
        const buildDescendantList = (parentId: string, depth: number = 1): Array<{ project: any; depth: number }> => {
          const directChildren = projects.filter((p) => p.parentId === parentId);
          let list: Array<{ project: any; depth: number }> = [];
          for (const child of directChildren) {
            list.push({ project: child, depth });
            list = list.concat(buildDescendantList(child.id, depth + 1));
          }
          return list;
        };

        return (
          <div className="flex flex-col divide-y divide-border/20">
            {rootProjects.map((rootProj) => {
              const descendants = buildDescendantList(rootProj.id);
              const projectTags = rootProj.tags || [];

              return (
                <div
                  key={rootProj.id}
                  className="group py-5 hover:bg-foreground/[0.02] transition-all rounded-lg px-3 cursor-pointer"
                  onClick={() => onNavigate?.('editor', rootProj.id)}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    setContextMenu({ project: rootProj, x: e.clientX, y: e.clientY });
                  }}
                >
                  <div className="flex items-start gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        {rootProj.category ? (
                          <div className="flex items-center gap-1.5 text-[11px] text-foreground-subtle">
                            <span
                              className="w-1.5 h-1.5 rounded-full shrink-0"
                              style={{ backgroundColor: rootProj.category.color }}
                            />
                            {rootProj.category.name}
                          </div>
                        ) : (
                          <div className="text-[11px] text-foreground-muted">Sans catégorie</div>
                        )}
                      </div>
                      <div className="flex items-center justify-between gap-4">
                        <div className="flex items-center gap-3 flex-1 min-w-0">
                          <h3 className="text-sm font-bold text-foreground truncate shrink-0">
                            {rootProj.title}
                          </h3>
                          {rootProj.description && (
                            <span className="text-xs text-foreground-muted truncate hidden sm:block flex-1">
                              {rootProj.description}
                            </span>
                          )}
                        </div>
                        
                        <div className="flex items-center gap-4 shrink-0">
                          {projectTags.length > 0 && (
                            <div className="flex items-center gap-1.5 hidden md:flex">
                              {projectTags.slice(0, 3).map((t: any) => {
                                const name = t.name || t;
                                return (
                                  <span
                                    key={t.id || name}
                                    className="text-[10px] text-foreground-subtle bg-foreground/[0.04] px-2 py-0.5 rounded-full"
                                  >
                                    #{name}
                                  </span>
                                );
                              })}
                              {projectTags.length > 3 && (
                                <span className="text-[10px] text-foreground-subtle">
                                  +{projectTags.length - 3}
                                </span>
                              )}
                            </div>
                          )}
                          <div className="text-[11px] text-foreground-subtle shrink-0 w-20 text-right">
                            {timeAgo(rootProj.updatedAt || rootProj.createdAt)}
                          </div>
                          {renderParticipants(rootProj)}
                        </div>
                      </div>
                    </div>
                  </div>

                  {descendants.length > 0 && (
                    <div className="mt-3 space-y-1">
                      {descendants.map(({ project: child, depth }) => (
                        <div
                          key={child.id}
                          className="flex items-center gap-2 py-2 text-sm hover:bg-foreground/[0.06] rounded-lg px-2 cursor-pointer text-foreground-muted hover:text-foreground transition-colors"
                          style={{ paddingLeft: `${depth * 20}px` }}
                          onClick={(e) => {
                            e.stopPropagation();
                            onNavigate?.('editor', child.id);
                          }}
                          onContextMenu={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            setContextMenu({ project: child, x: e.clientX, y: e.clientY });
                          }}
                        >
                          <svg className="w-4 h-4 text-border/60 shrink-0 border-border" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M6 0v14a2 2 0 0 0 2 2h10" />
                          </svg>
                          <span className="truncate">{child.title}</span>
                          {child.category && (
                            <span
                              className="w-1.5 h-1.5 rounded-full shrink-0 ml-1"
                              style={{ backgroundColor: child.category.color }}
                              title={child.category.name}
                            />
                          )}
                          <div className="ml-auto flex items-center gap-4 shrink-0">
                            <div className="text-[11px] text-foreground-subtle hidden sm:block w-20 text-right">
                              {timeAgo(child.updatedAt || child.createdAt)}
                            </div>
                            {renderParticipants(child)}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        );
      })()}

      {/* Context menu */}
      {contextMenu && (
        <div
          className="fixed z-50 w-48 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex flex-col gap-0.5"
          style={{ left: contextMenu.x, top: contextMenu.y }}
          onClick={(e) => e.stopPropagation()}
        >
          <button
            type="button"
            onClick={() => {
              onNavigate?.('editor', contextMenu.project.id);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
          >
            Ouvrir
          </button>
          
          <button
            type="button"
            onClick={() => {
              handleRenameProject(contextMenu.project.id, contextMenu.project.title);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
          >
            Renommer
          </button>

          <div className="border-t border-border my-1" />

          {/* Category Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Catégorie</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-44 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 animate-in fade-in slide-in-from-left-1 duration-100">
              <button
                type="button"
                onClick={() => {
                  handleUpdateCategory(contextMenu.project.id, null);
                  setContextMenu(null);
                }}
                className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
              >
                Sans catégorie
              </button>
              {categories.map((cat) => (
                <button
                  key={cat.id}
                  type="button"
                  onClick={() => {
                    handleUpdateCategory(contextMenu.project.id, cat.id);
                    setContextMenu(null);
                  }}
                  className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer flex items-center gap-1.5"
                >
                  <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: cat.color }} />
                  <span className="truncate">{cat.name}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Status Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Statut</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-32 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 animate-in fade-in slide-in-from-left-1 duration-100">
              {[
                { value: 'actif', label: 'Actif' },
                { value: 'brouillon', label: 'Brouillon' },
                { value: 'archivé', label: 'Archivé' }
              ].map((status) => (
                <button
                  key={status.value}
                  type="button"
                  onClick={() => {
                    handleUpdateStatus(contextMenu.project.id, status.value);
                    setContextMenu(null);
                  }}
                  className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
                >
                  {status.label}
                </button>
              ))}
            </div>
          </div>

          {/* projet principal Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Lier à un livre</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-48 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 max-h-56 overflow-y-auto animate-in fade-in slide-in-from-left-1 duration-100">
              <button
                type="button"
                onClick={() => {
                  handleUpdateParentProject(contextMenu.project.id, null);
                  setContextMenu(null);
                }}
                className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer"
              >
                Aucun (autonome)
              </button>
              {projects
                .filter((p) => p.id !== contextMenu.project.id && !p.parentId) // Only root projects can be parents
                .map((proj) => (
                  <button
                    key={proj.id}
                    type="button"
                    onClick={() => {
                      handleUpdateParentProject(contextMenu.project.id, proj.id);
                      setContextMenu(null);
                    }}
                    className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-background-hover rounded-lg cursor-pointer truncate"
                  >
                    {proj.title}
                  </button>
                ))}
            </div>
          </div>

          <div className="border-t border-border my-1" />

          <button
            type="button"
            onClick={() => {
              handleDeleteProject(contextMenu.project.id, contextMenu.project.title);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-red-400 hover:bg-red-500/10 rounded-lg cursor-pointer"
          >
            Supprimer
          </button>
        </div>
      )}

      {/* Create Project Modal */}
      <CreateProjectModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        categories={categories}
        defaultType={modalDefaultType}
        onSuccess={() => {
          fetchProjectsAndCats();
        }}
      />
    </div>
  );
};
