import React, { useState, useEffect, useRef } from 'react';
import {
  Search,
  X,
  Folder,
  Lock,
  Globe2,
  Clock,
  Trash2,
  LayoutDashboard,
  Network,
  Layers,
} from 'lucide-react';
import { searchApi, type SearchResultItem } from '../../lib/api.js';
import { cn } from '../../lib/utils.js';

export interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  onNavigate?: (view: string, projectId?: string) => void;
}

const RECENT_SEARCHES_KEY = 'gb_command_palette_history';
const MAX_RECENT_SEARCHES = 5;

interface QuickAction {
  id: string;
  title: string;
  description: string;
  view: string;
  icon: React.ComponentType<{ className?: string }>;
}

const QUICK_ACTIONS: QuickAction[] = [
  {
    id: 'act-dashboard',
    title: 'Tableau de bord',
    description: 'Statistiques, activités récentes et raccourcis',
    view: 'dashboard',
    icon: LayoutDashboard,
  },
  {
    id: 'act-graph',
    title: 'Carte Constellation',
    description: 'Visualiser la carte globale des livres',
    view: 'graph',
    icon: Network,
  },
  {
    id: 'act-projects',
    title: 'Tous les livres',
    description: 'Bibliothèque complète des livres',
    view: 'projects',
    icon: Layers,
  },
];

export const CommandPalette: React.FC<CommandPaletteProps> = ({
  isOpen,
  onClose,
  onNavigate,
}) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResultItem[]>([]);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [recentSearches, setRecentSearches] = useState<string[]>(() => {
    try {
      const saved = typeof localStorage !== 'undefined' ? localStorage.getItem(RECENT_SEARCHES_KEY) : null;
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const inputRef = useRef<HTMLInputElement>(null);
  const debounceTimerRef = useRef<any>(null);

  // Keyboard escape handler
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isOpen && e.key === 'Escape') {
        e.preventDefault();
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  // Autofocus input on open
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => {
        inputRef.current?.focus();
        inputRef.current?.select();
      }, 50);
      setSelectedIndex(0);
    } else {
      setQuery('');
      setResults([]);
    }
  }, [isOpen]);

  // Trigger debounced search api
  useEffect(() => {
    if (!isOpen) return;
    if (!query.trim()) {
      setResults([]);
      setIsLoading(false);
      return;
    }
    setIsLoading(true);

    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      try {
        const res = await searchApi.search({ q: query.trim(), limit: 15 });
        setResults(res.results || []);
        setSelectedIndex(0);
      } catch {
        setResults([]);
      } finally {
        setIsLoading(false);
      }
    }, 150);

    return () => {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    };
  }, [query, isOpen]);

  // Navigable list
  const navigableItems = React.useMemo(() => {
    if (!query.trim()) {
      return QUICK_ACTIONS.map(a => ({ type: 'action' as const, data: a }));
    }
    return results.map(r => ({ type: 'project' as const, data: r }));
  }, [query, results]);

  const saveRecentSearch = (term: string) => {
    const trimmed = term.trim();
    if (!trimmed) return;
    try {
      const updated = [
        trimmed,
        ...recentSearches.filter((s) => s.toLowerCase() !== trimmed.toLowerCase()),
      ].slice(0, MAX_RECENT_SEARCHES);
      localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify(updated));
      setRecentSearches(updated);
    } catch {}
  };

  const clearRecentSearches = () => {
    setRecentSearches([]);
    try {
      localStorage.removeItem(RECENT_SEARCHES_KEY);
    } catch {}
  };

  const handleSelect = (item: any) => {
    if (item.type === 'project') {
      saveRecentSearch(item.data.title);
      onClose();
      onNavigate?.('editor', item.data.id);
    } else if (item.type === 'action') {
      onClose();
      onNavigate?.(item.data.view);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (navigableItems.length > 0) {
        setSelectedIndex((selectedIndex + 1) % navigableItems.length);
      }
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (navigableItems.length > 0) {
        setSelectedIndex((selectedIndex - 1 + navigableItems.length) % navigableItems.length);
      }
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (navigableItems.length > 0 && navigableItems[selectedIndex]) {
        handleSelect(navigableItems[selectedIndex]);
      }
    }
  };

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center pt-16 px-4 bg-background/80 backdrop-blur-xs transition-opacity"
      onClick={onClose}
    >
      <div
        className="w-full max-w-xl bg-background border border-border rounded-xl shadow-lg overflow-hidden flex flex-col max-h-[70vh]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Simple Search bar */}
        <div className="flex items-center px-4 py-3 border-b border-border gap-3">
          <Search className="w-4 h-4 text-foreground-muted shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Rechercher un livre..."
            className="w-full bg-transparent text-sm text-foreground focus:outline-none placeholder:text-foreground-muted"
          />
          {isLoading && (
            <div className="w-3.5 h-3.5 border-2 border-foreground-muted border-t-transparent rounded-full animate-spin shrink-0" />
          )}
          {query && (
            <button
              type="button"
              onClick={() => setQuery('')}
              className="text-foreground-muted hover:text-foreground cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        {/* Results */}
        <div className="flex-1 overflow-y-auto p-2 space-y-1">
          {!query.trim() ? (
            <div className="space-y-3">
              {/* Recent searches history */}
              {recentSearches.length > 0 && (
                <div className="px-2 py-1">
                  <div className="flex items-center justify-between text-[10px] font-bold text-foreground-muted uppercase tracking-wider mb-1.5">
                    <span>Recherches récentes</span>
                    <button
                      type="button"
                      onClick={clearRecentSearches}
                      className="text-[10px] text-red-400 hover:underline cursor-pointer normal-case"
                    >
                      Vider l'historique
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {recentSearches.map((term, i) => (
                      <button
                        key={i}
                        type="button"
                        onClick={() => {
                          setQuery(term);
                          inputRef.current?.focus();
                        }}
                        className="px-2 py-1 bg-background-surface border border-border hover:border-foreground/20 rounded-lg text-xs text-foreground-muted hover:text-foreground cursor-pointer transition-colors"
                      >
                        {term}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {/* Quick actions */}
              <div className="px-2 py-1">
                <div className="text-[10px] font-bold text-foreground-muted uppercase tracking-wider mb-1.5">
                  Navigation rapide
                </div>
                <div className="space-y-0.5">
                  {QUICK_ACTIONS.map((act, i) => {
                    const isSelected = selectedIndex === i;
                    const Icon = act.icon;
                    return (
                      <button
                        key={act.id}
                        type="button"
                        onClick={() => handleSelect({ type: 'action', data: act })}
                        onMouseEnter={() => setSelectedIndex(i)}
                        className={cn(
                          'w-full text-left px-2.5 py-2 rounded-lg text-xs flex items-center justify-between cursor-pointer transition-all border border-transparent',
                          isSelected
                            ? 'bg-foreground/5 font-semibold text-foreground border-border/40'
                            : 'text-foreground-muted hover:text-foreground'
                        )}
                      >
                        <div className="flex items-center gap-2">
                          <Icon className="w-3.5 h-3.5" />
                          <span>{act.title}</span>
                        </div>
                        <span className="text-[9px] opacity-60 font-mono">aller</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          ) : results.length === 0 && !isLoading ? (
            <div className="py-8 text-center text-xs text-foreground-muted">
              Aucun résultat pour "{query}"
            </div>
          ) : (
            <div className="space-y-0.5">
              {results.map((proj, i) => {
                const isSelected = selectedIndex === i;
                const categoryName = typeof proj.category === 'object' && proj.category !== null ? proj.category.name : null;
                const categoryColor = typeof proj.category === 'object' && proj.category !== null ? proj.category.color : '#6366f1';
                return (
                  <button
                    key={proj.id}
                    type="button"
                    onClick={() => handleSelect({ type: 'project', data: proj })}
                    onMouseEnter={() => setSelectedIndex(i)}
                    className={cn(
                      'w-full text-left px-2.5 py-2 rounded-lg text-xs flex flex-col gap-1 cursor-pointer transition-all border border-transparent',
                      isSelected
                        ? 'bg-foreground/5 border-border/40 text-foreground'
                        : 'text-foreground hover:text-foreground'
                    )}
                  >
                    <div className="flex items-center justify-between w-full">
                      <div className="flex items-center gap-2 font-semibold">
                        <Folder className="w-3.5 h-3.5 text-foreground-muted shrink-0" />
                        <span className="truncate">{proj.title}</span>
                      </div>
                      {categoryName && (
                        <span
                          className="text-[9px] px-1.5 py-0.2 rounded-full border shrink-0 border-border"
                          style={{
                            borderColor: `${categoryColor}40`,
                            color: categoryColor,
                          }}
                        >
                          {categoryName}
                        </span>
                      )}
                    </div>
                    {proj.description && (
                      <p className="text-[10px] text-foreground-muted line-clamp-1 pl-5.5 font-normal">
                        {proj.description}
                      </p>
                    )}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Minimal Footer */}
        <div className="px-4 py-2 border-t border-border bg-background-surface/30 flex items-center justify-between text-[10px] text-foreground-muted font-mono select-none">
          <div className="flex items-center gap-3">
            <span>↑↓ naviguer</span>
            <span>↵ choisir</span>
            <span>ESC fermer</span>
          </div>
          {results.length > 0 && query.trim() && (
            <span>{results.length} résultats</span>
          )}
        </div>
      </div>
    </div>
  );
};

export default CommandPalette;
