import React, { useState, useEffect, useCallback } from 'react';
import { Plus, Network, CheckSquare, Square, FileText, Trash2 } from 'lucide-react';
import { dashboardApi, api } from '../../lib/api.js';
import type { DashboardSummary } from '../../types/dashboard.js';
import { useAuth } from '../../context/AuthContext.js';
import { CreateProjectModal } from '../projects/CreateProjectModal.js';
import { cn } from '../../lib/utils.js';

export interface DashboardViewProps {
  onNavigate?: (view: string, projectId?: string) => void;
  onCreateProject?: () => void;
}

export const DashboardView: React.FC<DashboardViewProps> = ({
  onNavigate,
  onCreateProject,
}) => {
  const { user } = useAuth();
  const [summary, setSummary] = useState<DashboardSummary | null>(null);
  const [categories, setCategories] = useState<any[]>([]);
  const [allProjects, setAllProjects] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [quickText, setQuickText] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [createModalType, setCreateModalType] = useState<'livre' | 'page' | 'feuille'>('livre');

  // Quick Note State
  const [notes, setNotes] = useState<any[]>([]);
  const [quickNoteText, setQuickNoteText] = useState('');
  const [isCreatingNote, setIsCreatingNote] = useState(false);

  const fetchNotes = useCallback(async () => {
    try {
      const res = await api.get<{ tasks: any[] }>('/api/tasks');
      setNotes(res.tasks || []);
    } catch {}
  }, []);

  const fetchSummary = useCallback(async () => {
    setIsLoading(true);
    try {
      const [data, catsRes, projRes] = await Promise.all([
        dashboardApi.getSummary(),
        api.get<{ categories: any[] }>('/api/categories'),
        api.get<{ projects: any[] }>('/api/projects'),
        fetchNotes(),
      ]);
      setSummary(data);
      setCategories(catsRes.categories || []);
      setAllProjects(projRes.projects || []);
    } catch {}
    setIsLoading(false);
  }, [fetchNotes]);

  useEffect(() => {
    fetchSummary();
  }, [fetchSummary]);

  const handleQuickNoteSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickNoteText.trim() || isCreatingNote) return;

    setIsCreatingNote(true);
    try {
      await api.post('/api/tasks', {
        title: quickNoteText.trim(),
        content: '',
      });
      setQuickNoteText('');
      fetchNotes();
    } catch {} finally {
      setIsCreatingNote(false);
    }
  };

  const handleToggleNoteStatus = async (note: any) => {
    try {
      const updatedStatus = !note.completed;
      setNotes((prev) =>
        prev.map((n) => (n.id === note.id ? { ...n, completed: updatedStatus } : n))
      );
      await api.patch(`/api/tasks/${note.id}`, { completed: updatedStatus });
      fetchNotes();
    } catch {
      fetchNotes();
    }
  };

  const handleDeleteNote = async (note: any) => {
    if (!window.confirm(`Supprimer la note "${note.title}" ?`)) return;
    try {
      setNotes((prev) => prev.filter((n) => n.id !== note.id));
      await api.delete(`/api/tasks/${note.id}`);
      fetchNotes();
    } catch {}
  };

  const handleQuickCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickText.trim() || isCreating) return;
    setIsCreating(true);
    try {
      const res = await dashboardApi.quickAdd({ text: quickText.trim(), space: 'personal' });
      setQuickText('');
      fetchSummary();
      if (res.project) {
        onNavigate?.('editor', res.project.id);
      }
    } catch {}
    setIsCreating(false);
  };

  const timeAgo = (date: Date | string | number) => {
    const now = Date.now();
    const d = typeof date === 'number' ? date * 1000 : new Date(date).getTime();
    const diff = Math.floor((now - d) / 1000);
    if (diff < 60) return "À l'instant";
    if (diff < 3600) return `Modifié : ${Math.floor(diff / 60)} min`;
    if (diff < 86400) return `Modifié : ${Math.floor(diff / 3600)} h`;
    if (diff < 604800) return `Modifié : ${Math.floor(diff / 86400)} j`;
    return `Modifié : ${new Date(d).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' })}`;
  };

  const recentProjects = summary?.recent_projects || summary?.recentProjects || [];

  // Right-click on project
  const [contextMenu, setContextMenu] = useState<{ project: any; x: number; y: number } | null>(null);
  useEffect(() => {
    const close = () => setContextMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, []);

  const handleDeleteProject = async (id: string, title: string) => {
    if (!window.confirm(`Supprimer "${title}" ?`)) return;
    try {
      await api.delete(`/api/projects/${id}`);
      fetchSummary();
    } catch {}
  };

  const handleRenameProject = async (projectId: string, currentTitle: string) => {
    const newTitle = prompt('Nouveau nom du livre :', currentTitle);
    if (newTitle && newTitle.trim() && newTitle.trim() !== currentTitle) {
      try {
        await api.patch(`/api/projects/${projectId}`, { title: newTitle.trim() });
        fetchSummary();
      } catch {}
    }
  };

  const handleUpdateCategory = async (projectId: string, catId: string | null) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { categoryId: catId });
      fetchSummary();
    } catch {}
  };

  const handleUpdateStatus = async (projectId: string, status: string) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { status });
      fetchSummary();
    } catch {}
  };

  const handleUpdateParentProject = async (projectId: string, parentId: string | null) => {
    try {
      await api.patch(`/api/projects/${projectId}`, { parentId });
      fetchSummary();
    } catch {}
  };

  return (
    <div className="flex-1 w-full max-w-2xl mx-auto px-6 py-10 overflow-y-auto" data-testid="dashboard-view">
      {/* Welcome */}
      <div className="mb-10 flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground tracking-tight">
            Bonjour{user?.name ? `, ${user.name}` : ''}
          </h1>
          <p className="text-sm text-foreground-muted mt-1">
            Que voulez-vous travailler aujourd'hui ?
          </p>
        </div>
        <button
          type="button"
          onClick={() => onNavigate?.('graph')}
          className="p-2 rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
          title="Carte nodale"
        >
          <Network className="w-5 h-5" />
        </button>
      </div>

      {/* Entity Creation Buttons - Elegant & Minimalist */}
      <div className="flex gap-3 mb-10">
        <button
          type="button"
          onClick={() => {
            setCreateModalType('livre');
            setIsCreateModalOpen(true);
          }}
          className="flex-1 py-3 px-4 bg-foreground text-background font-semibold rounded-xl text-xs flex items-center justify-center gap-1.5 hover:opacity-85 transition-opacity cursor-pointer shadow-xs"
        >
          <Plus className="w-3.5 h-3.5" />
          Nouveau Livre
        </button>
        <button
          type="button"
          onClick={() => {
            setCreateModalType('page');
            setIsCreateModalOpen(true);
          }}
          className="flex-1 py-3 px-4 bg-background-surface border border-border text-foreground font-semibold rounded-xl text-xs flex items-center justify-center gap-1.5 hover:bg-background-hover transition-colors cursor-pointer"
        >
          <Plus className="w-3.5 h-3.5" />
          Nouvelle Page
        </button>
        <button
          type="button"
          onClick={() => {
            setCreateModalType('feuille');
            setIsCreateModalOpen(true);
          }}
          className="flex-1 py-3 px-4 bg-background-surface border border-border text-foreground font-semibold rounded-xl text-xs flex items-center justify-center gap-1.5 hover:bg-background-hover transition-colors cursor-pointer"
        >
          <Plus className="w-3.5 h-3.5" />
          Nouvelle Feuille
        </button>
      </div>

      {/* Main Grid Content */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {/* Left Columns: Recent Books */}
        <div className="md:col-span-2 space-y-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xs font-semibold text-foreground-muted uppercase tracking-wider">
              Livres récents
            </h2>
            <button
              type="button"
              onClick={() => onNavigate?.('projects')}
              className="text-xs text-foreground-muted hover:text-foreground transition-colors cursor-pointer"
            >
              Voir tout →
            </button>
          </div>

          {isLoading ? (
            <div className="space-y-3">
              {[1, 2, 3].map((n) => (
                <div key={n} className="h-14 bg-background-surface border border-border rounded-xl animate-pulse" />
              ))}
            </div>
          ) : recentProjects.length === 0 ? (
            <div className="py-12 text-center border border-dashed border-border rounded-xl bg-background-surface/10">
              <p className="text-sm text-foreground-muted">Aucun livre pour l'instant</p>
              <button
                type="button"
                onClick={onCreateProject}
                className="mt-3 text-sm text-foreground hover:underline cursor-pointer"
              >
                Créer votre premier livre
              </button>
            </div>
          ) : (
            <div className="space-y-4">
              {recentProjects.map((proj: any) => (
                <div
                  key={proj.id}
                  onClick={() => onNavigate?.('editor', proj.id)}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    setContextMenu({ project: proj, x: e.clientX, y: e.clientY });
                  }}
                  className="w-full text-left p-5 rounded-2xl bg-background-surface/[0.15] border border-border/20 hover:border-border/65 hover:bg-background-surface/[0.25] transition-all duration-300 cursor-pointer flex flex-col gap-3 group"
                >
                  <div className="flex items-center justify-between gap-4">
                    <div className="flex items-center gap-2.5 min-w-0">
                      {proj.category?.color ? (
                        <span
                          className="w-2.5 h-2.5 rounded-full shrink-0 shadow-xs"
                          style={{ backgroundColor: proj.category.color }}
                        />
                      ) : (
                        <span className="w-2.5 h-2.5 rounded-full shrink-0 bg-foreground/20" />
                      )}
                      <span className="text-sm font-bold text-foreground truncate">
                        {proj.title}
                      </span>
                    </div>

                    <div className="text-[10px] font-mono text-foreground-subtle shrink-0">
                      {timeAgo(proj.updatedAt || proj.createdAt)}
                    </div>
                  </div>

                  {proj.description && (
                    <p className="text-xs text-foreground-muted line-clamp-2">
                      {proj.description}
                    </p>
                  )}

                  {proj.tags && proj.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1.5">
                      {proj.tags.map((tag: string, i: number) => (
                        <span key={i} className="text-[9px] font-medium text-foreground-subtle bg-foreground/[0.04] px-2 py-0.5 rounded-full border border-border/10">
                          #{tag}
                        </span>
                      ))}
                    </div>
                  )}

                  {proj.recentlyModifiedPages && proj.recentlyModifiedPages.length > 0 && (
                    <div className="pt-3 mt-1 border-t border-border/10 flex flex-col gap-1.5">
                      <div className="text-[9px] font-bold text-foreground-subtle uppercase tracking-wider mb-0.5">
                        Modifications récentes :
                      </div>
                      <div className="flex flex-col gap-1">
                        {proj.recentlyModifiedPages.map((page: any) => (
                          <div
                            key={page.id}
                            onClick={(e) => {
                              e.stopPropagation();
                              onNavigate?.('editor', page.id);
                            }}
                            className="flex items-center justify-between gap-2 text-[11px] text-foreground-subtle hover:text-foreground hover:bg-foreground/[0.03] px-2.5 py-1 rounded-lg transition-colors cursor-pointer"
                          >
                            <div className="flex items-center gap-1.5 min-w-0">
                              <span className="text-foreground-subtle/30 text-[9px] select-none">└</span>
                              <span className="truncate font-medium">{page.title}</span>
                            </div>
                            <span className="text-[9px] text-foreground-subtle/60 shrink-0 italic">
                              {timeAgo(page.updatedAt)}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Right Column: Quick Note & Checklist */}
        <div className="md:col-span-1 space-y-6">
          <div>
            <h2 className="text-xs font-semibold text-foreground-muted uppercase tracking-wider mb-4">
              Notes rapides
            </h2>
            <div className="bg-background-surface/30 border border-border/20 rounded-xl p-4 space-y-4">
              {/* Quicknote Input form */}
              <form onSubmit={handleQuickNoteSubmit}>
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={quickNoteText}
                    onChange={(e) => setQuickNoteText(e.target.value)}
                    placeholder="Note rapide..."
                    className="flex-1 px-3 py-2 bg-background border border-border rounded-xl text-xs text-foreground placeholder:text-foreground-subtle focus:outline-none focus:border-foreground/30 transition-colors"
                  />
                  <button
                    type="submit"
                    disabled={!quickNoteText.trim() || isCreatingNote}
                    className="px-3 py-2 bg-foreground text-background rounded-xl text-xs font-semibold hover:opacity-85 disabled:opacity-40 cursor-pointer"
                  >
                    <Plus className="w-3.5 h-3.5" />
                  </button>
                </div>
              </form>

              {/* Checklist representation of active notes/tasks */}
              {isLoading ? (
                <div className="space-y-2 animate-pulse">
                  <div className="h-6 bg-background rounded" />
                  <div className="h-6 bg-background rounded" />
                </div>
              ) : notes.filter((n) => !n.completed).length === 0 ? (
                <div className="text-center py-4">
                  <FileText className="w-6 h-6 text-foreground-muted/30 mx-auto mb-1" />
                  <p className="text-[11px] text-foreground-muted italic">Aucune note active</p>
                </div>
              ) : (
                <div className="space-y-2 max-h-56 overflow-y-auto pr-1">
                  {notes
                    .filter((n) => !n.completed)
                    .slice(0, 5) // Show top 5 active notes
                    .map((note) => (
                      <div
                        key={note.id}
                        className="flex items-start justify-between gap-2 p-2 rounded-lg bg-background/40 hover:bg-background/80 transition-colors border border-border/10 group"
                      >
                        <div className="flex items-start gap-2 min-w-0 flex-1">
                          <button
                            type="button"
                            onClick={() => handleToggleNoteStatus(note)}
                            className="mt-0.5 text-foreground-subtle hover:text-foreground cursor-pointer shrink-0"
                          >
                            <Square className="w-3.5 h-3.5" />
                          </button>
                          <span className="text-xs text-foreground select-text whitespace-pre-wrap break-words flex-1">
                            {note.title}
                          </span>
                        </div>
                        <button
                          type="button"
                          onClick={() => handleDeleteNote(note)}
                          className="opacity-0 group-hover:opacity-100 text-foreground-muted hover:text-red-400 p-0.5 rounded cursor-pointer transition-opacity"
                        >
                          <Trash2 className="w-3 h-3" />
                        </button>
                      </div>
                    ))}
                </div>
              )}

              {/* View all notes link */}
              <button
                type="button"
                onClick={() => onNavigate?.('notes')}
                className="w-full text-center text-[10px] text-foreground-muted hover:text-foreground hover:underline transition-colors block font-semibold cursor-pointer"
              >
                Gérer toutes les notes ({notes.length}) →
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Context menu */}
      {contextMenu && (
        <div
          className="fixed z-50 w-48 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex flex-col gap-0.5"
          style={{ left: contextMenu.x, top: contextMenu.y }}
          onClick={(e) => e.stopPropagation()}
        >
          <button
            type="button"
            onClick={() => {
              onNavigate?.('editor', contextMenu.project.id);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
          >
            Ouvrir
          </button>
          
          <button
            type="button"
            onClick={() => {
              handleRenameProject(contextMenu.project.id, contextMenu.project.title);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
          >
            Renommer
          </button>

          <div className="border-t border-border my-1" />

          {/* Category Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Catégorie</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-44 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 animate-in fade-in slide-in-from-left-1 duration-100">
              <button
                type="button"
                onClick={() => {
                  handleUpdateCategory(contextMenu.project.id, null);
                  setContextMenu(null);
                }}
                className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
              >
                Sans catégorie
              </button>
              {categories.map((cat) => (
                <button
                  key={cat.id}
                  type="button"
                  onClick={() => {
                    handleUpdateCategory(contextMenu.project.id, cat.id);
                    setContextMenu(null);
                  }}
                  className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer flex items-center gap-1.5"
                >
                  <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: cat.color }} />
                  <span className="truncate">{cat.name}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Status Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Statut</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-32 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 animate-in fade-in slide-in-from-left-1 duration-100">
              {[
                { value: 'active', label: 'Actif' },
                { value: 'draft', label: 'Brouillon' },
                { value: 'archived', label: 'Archivé' },
              ].map((s) => (
                <button
                  key={s.value}
                  type="button"
                  onClick={() => {
                    handleUpdateStatus(contextMenu.project.id, s.value);
                    setContextMenu(null);
                  }}
                  className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
                >
                  {s.label}
                </button>
              ))}
            </div>
          </div>

          {/* Lier à un projet Submenu */}
          <div className="relative group">
            <button
              type="button"
              className="w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer flex items-center justify-between"
            >
              <span>Lier à un livre</span>
              <span className="text-[9px] text-foreground-subtle">➔</span>
            </button>
            <div className="hidden group-hover:flex absolute left-full top-0 ml-0.5 w-48 bg-background-surface border border-border rounded-xl p-1 shadow-lg flex-col gap-0.5 max-h-56 overflow-y-auto animate-in fade-in slide-in-from-left-1 duration-100">
              <button
                type="button"
                onClick={() => {
                  handleUpdateParentProject(contextMenu.project.id, null);
                  setContextMenu(null);
                }}
                className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer"
              >
                Aucun (autonome)
              </button>
              {allProjects
                .filter((p) => p.id !== contextMenu.project.id && !p.parentId) // Only root projects can be parents
                .map((proj) => (
                  <button
                    key={proj.id}
                    type="button"
                    onClick={() => {
                      handleUpdateParentProject(contextMenu.project.id, proj.id);
                      setContextMenu(null);
                    }}
                    className="w-full text-left px-2.5 py-1.5 text-xs text-foreground hover:bg-foreground/[0.04] rounded-lg cursor-pointer truncate"
                  >
                    {proj.title}
                  </button>
                ))}
            </div>
          </div>

          <div className="border-t border-border my-1" />

          <button
            type="button"
            onClick={() => {
              handleDeleteProject(contextMenu.project.id, contextMenu.project.title);
              setContextMenu(null);
            }}
            className="w-full text-left px-3 py-1.5 text-xs text-red-400 hover:bg-red-500/10 rounded-lg cursor-pointer"
          >
            Supprimer
          </button>
        </div>
      )}

      {/* Create Project Modal */}
      <CreateProjectModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        categories={categories}
        defaultType={createModalType}
        onSuccess={() => {
          fetchSummary();
        }}
      />
    </div>
  );
};

export default DashboardView;
